import { NotFoundError, ValidationError } from "../domain/errors";
import { ProjectRepository } from "../domain/project";
import { Task, TaskFilter, TaskRepository, TaskStatus } from "../domain/task";
import { UserRepository } from "../domain/user";
import { Clock, IdGenerator } from "./ports";

export interface AddTaskCommand {
  projectId: string;
  title: string;
  description: string;
  dueDate?: Date;
  status?: TaskStatus;
  assigneeId?: string;
}

export class TaskService {
  constructor(
    private readonly tasks: TaskRepository,
    private readonly projects: ProjectRepository,
    private readonly users: UserRepository,
    private readonly ids: IdGenerator,
    private readonly clock: Clock,
  ) {}

  add(command: AddTaskCommand): Task {
    this.requireProject(command.projectId);
    if (command.assigneeId !== undefined) {
      this.requireUser(command.assigneeId);
    }
    const task = new Task({
      id: this.ids.next(),
      projectId: command.projectId,
      title: command.title,
      description: command.description,
      dueDate: command.dueDate,
      status: command.status,
      assigneeId: command.assigneeId,
      createdAt: this.clock.now(),
    });
    this.tasks.save(task);
    return task;
  }

  get(projectId: string, taskId: string): Task {
    this.requireProject(projectId);
    const task = this.tasks.findById(taskId);
    if (!task || task.projectId !== projectId) {
      throw new NotFoundError("Task", taskId);
    }
    return task;
  }

  list(projectId: string, filter: TaskFilter = {}): Task[] {
    this.requireProject(projectId);
    return this.tasks.findByProject(projectId, filter);
  }

  assign(projectId: string, taskId: string, userId: string): Task {
    const task = this.get(projectId, taskId);
    this.requireUser(userId);
    task.assignTo(userId);
    this.tasks.save(task);
    return task;
  }

  markDone(projectId: string, taskId: string): Task {
    const task = this.get(projectId, taskId);
    task.markDone(this.clock.now());
    this.tasks.save(task);
    return task;
  }

  private requireProject(id: string): void {
    if (!this.projects.findById(id)) {
      throw new NotFoundError("Project", id);
    }
  }

  private requireUser(id: string): void {
    if (!this.users.findById(id)) {
      throw new ValidationError(`Assignee '${id}' is not an existing user`);
    }
  }
}

=====SOURCE-END=====

